import com.github.cliftonlabs.json_simple.Jsoner;
import com.github.cliftonlabs.json_simple.JsonObject;
import com.github.cliftonlabs.json_simple.JsonArray;
import java.io.IOException;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;

public class ComparePopulationDensities {

    private static final String API_URL = "https://api.worldpopulation.io/v2/countries/";

    public static void main(String[] args) throws IOException, InterruptedException {
        if (args.length != 2) {
            System.err.println("Usage: java ComparePopulationDensities <country1> <country2>");
            return;
        }

        String country1 = args[0];
        String country2 = args[1];

        JsonObject countryData1 = getCountryData(country1);
        JsonObject countryData2 = getCountryData(country2);

        if (countryData1 == null || countryData2 == null) {
            System.err.println("Error fetching data for one or both countries.");
            return;
        }

        long population1 = countryData1.getLong("population");
        double area1 = countryData1.getDouble("area");
        long population2 = countryData2.getLong("population");
        double area2 = countryData2.getDouble("area");

        double density1 = population1 / area1;
        double density2 = population2 / area2;

        System.out.printf("Population density of %s: %.2f people per sq km%n", country1, density1);
        System.out.printf("Population density of %s: %.2f people per sq km%n", country2, density2);

        if (density1 > density2) {
            System.out.printf("%s has a higher population density than %s.%n", country1, country2);
        } else if (density1 < density2) {
            System.out.printf("%s has a higher population density than %s.%n", country2, country1);
        } else {
            System.out.printf("%s and %s have the same population density.%n", country1, country2);
        }
    }

    private static JsonObject getCountryData(String country) throws IOException, InterruptedException {
        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(API_URL + country))
                .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

        if (response.statusCode() != 200) {
            System.err.println("Error fetching data for " + country + ": " + response.statusCode());
            return null;
        }

        JsonObject countryData = (JsonObject) Jsoner.deserialize(response.body());
        return countryData;
    }
}
```

Replace `<country1>` and `<country2>` with the names of the countries you want to compare. The program will output the population densities of both countries and indicate which one has a higher population density.
