   ```csharp
   services.AddAuthentication(BasicAuthenticationDefaults.AuthenticationScheme)
       .AddBasicAuthentication(options =>
       {
           options.Realm = "YourRealmName";
           options.Events = new BasicAuthenticationEvents
           {
               OnValidatePrincipal = context =>
               {
                   // Validate the username and password here
                   if (context.Username == "your_username" && context.Password == "your_password")
                   {
                       var claims = new List<Claim>
                       {
                           new Claim(ClaimTypes.Name, context.Username)
                       };

                       var identity = new ClaimsIdentity(claims, BasicAuthenticationDefaults.AuthenticationScheme);
                       var principal = new ClaimsPrincipal(identity);

                       context.Principal = principal;
                       context.Success();
                   }

                   return Task.CompletedTask;
               }
           };
       });
   ```

3. In the `Configure` method, add the following code to enable authentication and authorization:

   ```csharp
   app.UseAuthentication();
   app.UseAuthorization();
   ```

